(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,16875,e=>{"use strict";var l=e.i(43476),i=e.i(11337);function n(e){let n={li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.useMDXComponents)(),...e.components},{AnketaCollapse:r,AnketaGroup:c,AnketaList:d,AnketaPoint:h,AnketaProse:j,Whisper:x}=n;return r||s("AnketaCollapse",!0),c||s("AnketaGroup",!0),d||s("AnketaList",!0),h||s("AnketaPoint",!0),j||s("AnketaProse",!0),x||s("Whisper",!0),(0,l.jsxs)(c,{children:[(0,l.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,l.jsxs)(d,{children:[(0,l.jsxs)(h,{title:"Имя персонажа [русс|англ]",children:[(0,l.jsx)(n.p,{children:(0,l.jsx)(n.strong,{children:"Орэбелла Конте | Orabella Conte"})}),(0,l.jsxs)(n.ul,{children:["\n",(0,l.jsxs)(n.li,{children:["Полное имя: ",(0,l.jsx)(n.strong,{children:"Орэбелла-Летиция Конте"}),". В Энкраже не пользуется вторым именем уже давно;"]}),"\n",(0,l.jsxs)(n.li,{children:["Сокращённое имя – ",(0,l.jsx)(n.strong,{children:"Белла"}),";"]}),"\n",(0,l.jsxs)(n.li,{children:["Прозвища: ",(0,l.jsx)(n.strong,{children:"Мать"}),", ",(0,l.jsx)(n.strong,{children:"Цветок Осени"})," (при жизни, перенесла это прозвище в Энкраж), ",(0,l.jsx)(n.strong,{children:"Госпожа Грация"}),"."]}),"\n"]})]}),(0,l.jsx)(h,{title:"Возраст",children:(0,l.jsxs)(n.ul,{children:["\n",(0,l.jsx)(n.li,{children:"прожитый на земле: 30 лет."}),"\n",(0,l.jsx)(n.li,{children:"дата рождения — 25.10.1653г. | смерти — 02.11.1683г."}),"\n",(0,l.jsx)(n.li,{children:"прожитый в Загробном мире как грешная душа: 335 лет"}),"\n"]})}),(0,l.jsx)(h,{title:"Пол",children:(0,l.jsx)(n.p,{children:"Женский"})}),(0,l.jsxs)(h,{title:"Раса",children:[(0,l.jsx)(n.p,{children:"Акрабуамелу."}),(0,l.jsxs)(n.ul,{children:["\n",(0,l.jsx)(n.li,{children:"Белла при жизни очень любила жизнь, полную благ. Роскошь окружала её с самого младенчества, и Императрица впоследствии делала всё, чтобы так и продолжалось. Богатые наряды, сверкающие украшения, нескромное убранство жилья. И всегда хотелось больше. Преумножать;"}),"\n",(0,l.jsx)(n.li,{children:"Будущая акрабуамелу также любила путешествия. Видеть новые места, наблюдать многообразие мира, впитывать их. И быть немножко другой, нежели вчера;"}),"\n",(0,l.jsx)(n.li,{children:"Крепкие семейные узы. Когда в радость заботиться о родных, защищать их;"}),"\n",(0,l.jsx)(n.li,{children:"Капризы. Данную черту, пусть и нехотя, взрастили в девушке родители. Они баловали ей, потакали любым запросам, и Орэбелла принимала это как данность. Так продолжается и по сей день;"}),"\n",(0,l.jsx)(n.li,{children:"Матриархальное начало. Женское обаяние, хитрость, мудрые наставления матушки сделали всё, чтобы брак Беллы был максимально комфортным. При этом всё не выглядело как однозначная власть супруги;"}),"\n",(0,l.jsx)(n.li,{children:"Коррумпированность. Имел место быть как мелкий подкуп, так и более крупный, ради больших благ."}),"\n"]})]})]})}),(0,l.jsxs)(r,{title:"Психологический профиль",children:[(0,l.jsx)(r,{title:"Характер",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(n.p,{children:"Кто-то может сказать, что такое сочетание качеств – сущее проклятье. Но разве оно не прекрасно?"}),(0,l.jsx)(n.p,{children:"Нежный, нежный цветок, ради которого даже Солнце готово задержаться на небесном своде. Его лепестки мягки и притягательны, ими хочется любоваться, оберегать."}),(0,l.jsx)(n.p,{children:"Орэбелла притягивает к себе людей: будь то приятный слуху голос, грациозный, лёгкий жест, очаровательная и кокетливая улыбка. Она легка и изящна, мила и доброжелательна, безупречна в манерах. Императрице не составляет труда расположить к себе собеседника, завлечь того в увлекательную беседу, заставить себя слушать, найти подход."}),(0,l.jsx)(n.p,{children:"Притворством ли является вышесказанное? Нет. Это часть Беллы. Даже если она кажется несколько театральной и неестественной, но не фальшивой или полной лицемерия. Разве что за некоторыми исключениями, когда необходимо извлечь какую-то пользу, выгоду. Ей бесконечно нравится общество и общение, особенно то, которое выказывает почёт и восхищение её персоной. Но это мешает одновременно быть в некотором роде отстранённой от этого. Особенность Акрабуамелу – нежелание подпускать чужаков очень близко к клану, сородичам. Ей также не прельщают сплетни и интриги: она их не распространяет и не желает слышать, если это касается самой грешницы. А потому следит за тем, чтобы подобного было как можно меньше."}),(0,l.jsx)(n.p,{children:"Безусловно, описанные качества положительно способствуют другим: наблюдательность, хитрость, расчетливость, острый, живой ум. В связке получается без особенных усилий получать нужную, важную информацию: о мире, грешниках, врагах и союзниках. И манипулировать ею, дёргать за ниточки словно куклу, когда придёт время. Ради себя, своего благополучия, а также благополучия клана. Этот мир жесток, он благоволит сильным, живучим, изворотливым. Клан – это великая ответственность, и будет большой ошибкой несерьезно относиться к своим обязанностям. Не стоит забывать о внутренней конкуренции, ведь какая женщина в тайне (или нет) не мечтает стать Императрицей. Информация – власть. Мать властолюбива и любит отдавать приказы и требовать исполнения."}),(0,l.jsx)(n.p,{children:"Не стоит заблуждаться касательно личности Конте: она может казаться ранимой, ведь цветы так легко сломать. Но они также умеют защищаться, и Орэбелла не является исключением. Стоит только попытаться причинить вред, и выяснится, что корни её прочны и с невероятным рвением держатся в земле, а несгибаемый стальной стержень усыпан шипами. Но самое опасное – нектар. Стоит вкусить его, и нагрянет агония, которая с радостью заключит в свои объятья. О да, Мать может и умеет быть жестокой и коварной, даже получает некоторое удовольствие от подобных качеств."}),(0,l.jsx)(n.p,{children:"По-настоящему, если уж быть до конца откровенным рассказчиком, характер акрабуамелу не прост. Будучи требовательной и капризной, у неё высокие запросы на эту жизнь, и она будет делать всё, чтобы их исполнить. Своими или чужими руками, шаг за шагом, кирпичик за кирпичиком."}),(0,l.jsx)(n.p,{children:"Отсюда мы плавно подходим к такой черте как жадность. Боги, как же Белла алчна. Вещи, предметы, драгоценности, внимание, любовь, обожание, почитание от мужчин или женщин – ей всегда будет мало. Она будет бесконечно желать всего этого, как всякий цветок желает удобрений, воды и света Солнца, чтобы пребывать в наилучших условиях. И ей никогда не будет достаточно. Страшно представить, на что может пойти Императрица ради нового платья или драгоценного ожерелья на шее другой женщины. И пусть весь мир падет ниц перед ногами Орэбеллы в этот момент, захлебнётся кровью или взвоет от боли. Девушка искренне не считает нужным прятать непристойный грех, сдерживать его. Зачем, если его можно удовлетворить?"}),(0,l.jsx)(n.p,{children:"В силу гордой натуры очень тяжело воспринимает отказы или вовсе их игнорирует. Способна на ложь, лицемерие, хорошую имитацию эмоций, ведь это отличные инструменты влияния, которое Конте необходимы."}),(0,l.jsx)(n.p,{children:"Приступы гнева и агрессии не свойственны Императрице. Она вполне спокойно, прямо или косвенно даст понять, что не потерпит недостойного к себе отношения. Будь то мягкое, едва заметное замечание или жалящие слова – зависит от обстоятельств и собеседников. И настроения, разумеется. При этом достаточно терпелива, когда это не касается доминирующего греха. Конте умеет затаиться, подождать, играть в долгую, если то требуется. В дурных исходах старается увидеть плюсы, научиться на ошибках, адаптироваться. Не поспешит с принятием важных решений, подумает, попытается увидеть последствия тех или иных решений."}),(0,l.jsx)(n.p,{children:"Она может легко забывать обстоятельства и людей, которым причинила вред, как моральный, так и физический. Разумеется, когда речь идёт о каких-то незначительных стычках, в отношении тех, кто Белле неинтересен. Воистину, девушка не заботится о чувствах других. В основном это касается не сородичей, но и те могут ощутить безразличие Матери. Пройдёт время, и Конте, как ни в чём не бывало, заведёт непринуждённую беседу с тем, кого некогда обидела, будет улыбаться и всячески к себе располагать."}),(0,l.jsx)(n.p,{children:"Как и любой, без преувеличения, из клана, Орэбелла не может долго усидеть на одном месте. Ей бесконечно импонирует перемещаться с места на место, чтобы познать новые территории, а также заново изучить старые. Атмосфера странствия, возможность видеть разнообразные пейзажи, дышать другим воздухом и слышать шум волн неспокойных вод, чтобы тепло вспоминать обо всём этом, разделять между сородичами, ощущать единство."}),(0,l.jsx)(n.p,{children:"Белле также свойственна жажда новизны на более приземлённом уровне, будь то одежда или обстановка в комнате. Девушка часто меняет что-то в своих нарядах, очень любит моду разных эпох. Разве что к современной относится крайне осторожно, полагая, что та не отражает личность Императрицы и её статус. То же касается и культуры в целом: ей очень нравится читать о том, что же происходило в мире. Это ведь такая замечательная возможность: быть мертвой, но не терять связи с реальностью, видеть её переменчивость и меняться вместе, хоть это не всегда просто. Всё же информация из источников помогает представить, но не прожить. Ты словно подсматриваешь за другими, не имея возможности присоединиться полноценно. Есть в этом что-то меланхоличное."}),(0,l.jsx)(n.p,{children:"Стоит также упомянуть о таких качествах Матери как ответственность, благородство, умение проявлять заботу и сострадание. Она может обладать не самыми приятными качествами, демонстрировать их и не стыдиться, быть невыносимой до зубовного скрежета, однако, в силу своего положения, некоторых убеждений и любви по отношению к сородичам, Белла с готовностью принимает на свои хрупкие плечи ношу, стойко преодолевая препятствия и тяготы. Она способна защищать, рьяно и порой отчаянно, готова брать ответственность за слова и поступки как свои, так и других. Знает вес и ценность своих слов, понимает последствия тех или иных решений. Или пытается понять."}),(0,l.jsx)(n.p,{children:"Но что же на счёт любви? О, это прекрасное, замечательное чувство, толкающее на самые невероятные и ужасные поступки. Белла полна любви. Прежде всего, к себе. Но и другие вполне способны её ощутить, вполне искреннюю. Если будут одаривать Мать, то она, безусловно, ответит взаимностью, и то будет лучшим подарком. При этом не остановится на ком-то одном. Белла полигамна, её любви на всех хватит. Даже если сама Конте в некоторой степени эгоистична и, возможно, ревнива в определённом смысле. Ей просто невыносима сама мысль связать себя с одним партнёром. Поэтому Императрица поклялась себе не заводить моногамных отношений."}),(0,l.jsx)(n.p,{children:"Как истинная белоручка не слишком приспособлена к бытовому труду, хотя обладает кое-какими навыками. Зачем, когда можно потратить время на более полезные вещи и всё и так сделают за тебя. Исключение составляет комната и личные вещи Беллы, с которыми она управляется самостоятельно и тщательно охраняет. Считает, что в быту должен быть порядок и чистота. В некоторой степени брезглива и очень аккуратна: осталось от прошлой жизни. Даже в самых непритязательных условиях постарается обустроиться с максимальным для себя комфортом."}),(0,l.jsx)(n.p,{children:"Имеет пристрастие к изысканным и редким блюдам. Белла совсем не обжора, однако не может себе отказать в желании насладиться определённой пищей. Она нарочно себя «терзает», чтобы затем с бОльшим удовольствием ублажить свои рецепторы."})]})}),(0,l.jsx)(r,{title:"Страхи",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Утрата власти",children:(0,l.jsx)(n.p,{children:"«И всё станет зыбким, словно песок, ускользающий из пальцев». Орэбелла ощутимо боится утраты власти, влияния, восхищённого внимания к своей персоне, потери накопленных благ. Перечисленное для неё – данность, без которой трудно или даже невозможно представить своё бытие. Она боится попросту оказаться никому ненужной. И это несмотря на уверенность в себе и своих силах."})}),(0,l.jsx)(h,{title:"Потеря клана",children:(0,l.jsx)(n.p,{children:"«Мы сильны, пока мы вместе». Также Императрица боится потерять клан. Боится за всех их, за их жизни. Что её сородичи утратят своё благополучие, будут уничтожены, ведь от этого также зависит и благополучие Беллы."})}),(0,l.jsx)(h,{title:"Постоянство",children:(0,l.jsx)(n.p,{children:"«Остановиться, значит перестать существовать». Страх постоянства. Ведь Конте очень важны перемены, даже самые маленькие."})}),(0,l.jsx)(h,{title:"Забвение",children:(0,l.jsx)(n.p,{children:"«Умереть и остаться забытым. Словно бы и не было тебя в этом мире». Страх смерти, страх остаться забытой после неё, не оставить ничего. Банально, но значимо."})}),(0,l.jsx)(h,{title:"Предательство в любви",children:(0,l.jsx)(n.p,{children:"«Я никого не смогу любить, кроме тебя». Неприятно и боязно представить, как отдашь своё сердце и душу кому-то одному. Особенно когда тот окажется предателем."})}),(0,l.jsx)(h,{title:"Холод",children:(0,l.jsx)(n.p,{children:"«И хлад закуёт свои ледяные цепи, насылая губительный сон». Конте довольно теплолюбива и довольно легко переносит высокие температуры. Но не наоборот. Девушка теряет работоспособность, становится пассивной и менее внимательной, более раздражительной. Белла искренне боится потерять хватку, уснуть, впасть в анабиоз или вовсе умереть. Даже с опаской посматривает на сквозняки и никогда не перемещается в холодное время года. В такие моменты статичность подобна мучениям."})}),(0,l.jsx)(h,{title:"Уродство",children:(0,l.jsx)(n.p,{children:"«Тело твоё безобразно, и даже зеркало не способно выдержать твой облик». Белла очень боится внешнего уродства, утраты привлекательности, утраты функционирующих конечностей, даже на время. Особенно это касается жала."})}),(0,l.jsx)(h,{title:"Ментальное воздействие",children:(0,l.jsx)(n.p,{children:"«Ты – марионетка в руках моих». Страх ментального воздействия преследует Мать уже довольно давно и никуда не уходит. Хуже, когда осознаёшь управление собой, но ничего не можешь с этим поделать. И неизвестно, что кукловод затребует."})}),(0,l.jsx)(h,{title:"Огонь",children:(0,l.jsx)(n.p,{children:"«Посмотри, как охотно пламя пожирает твою плоть». Когда огня немного, и он контролируем, Белла ещё может находиться рядом. Но только в таком случае. В остальном – это страх."})})]})}),(0,l.jsx)(r,{title:"Мечты, цели",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(n.p,{children:"«Я возвышусь. Ты падешь». Императрица мечтает достигнуть небывалого величия клана. Укрепить его так, чтобы ни один враг не осмелился даже на косой взгляд. Ей искренне хочется видеть сплоченность в рядах сородичей."}),(0,l.jsx)(n.p,{children:"«И все богатства мира коснутся моих пальцев». Жадность всегда толкает на желание обладать. Конте мечтает и стремится к тому, чтобы быть самой богатой, обладать наибольшим количеством ресурсов во всём Энкраже."}),(0,l.jsx)(n.p,{children:"«Мне нравится то, как вы меня любите». Императрица лелеет надежду на то, чтобы её любили, уважали, испытывали желание, влечение."}),(0,l.jsx)(n.p,{children:"«Жизнь восхитительна, если тянется бесконечно». Орэбелла желает продлить свои годы в Энкраже. Главное – уплатить за это как можно меньшую цену."}),(0,l.jsx)(n.p,{children:"«Не ведают мёртвые, как ярко светит Солнце живым». Мечты не всегда должны быть сбыточными, но кто знает. Конте хотелось бы когда-нибудь ощутить согревающие лучи Солнца на своей коже. Вдохнуть полной грудью воздух. Иметь возможность быть живой и общаться с живыми. И без процесса перерождения."}),(0,l.jsx)(n.p,{children:"«И знания свои я передам тем, кто будет после меня, и кто пойдёт за мной». Императрица пожелала оставить свой след в письменных трудах. Делиться своим жизненным опытом, упрощая жизнь другим сородичам. Пока имеет только наработки."})]})}),(0,l.jsx)(r,{title:"Биография (при жизни)",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(x,{children:(0,l.jsx)(n.p,{children:"Мне была ведома прекрасная жизнь. Ах, как много она мне дала и ещё могла бы дать!"})}),(0,l.jsx)(n.p,{children:"Несмотря на исторические события, происходящие в Венецианской Республике 17 века, неизменно ведущие ту к упадку и утрате самостоятельности, Королева Адриатики всё ещё имела свои вес и силу. Фундамент, выстроенный и закреплённый на протяжении многих столетий, ещё не был разрушен, хоть и давал трещины. В это же время, на закате 1653 года, родилась будущая Императрица. Под счастливой звездой, надо сказать: род Ренальди был достаточно влиятельным и сохранял свои позиции довольно долго. Так, отец Беллы, Маттео Ренальди, дворянин по крови, занимал почётное место в Большом Совете, имел титул виконта и солидный капитал, позволявший ему развиваться в различных направлениях. Главным было ростовщичество, торговля – второстепенным. И то и другое у него отлично получалось. Маттео славился непростым нравом: мужчина редко прощал ошибки и оплошности, не терпел заискиваний и льстивых улыбок, любил всё контролировать, держать в достаточно жестких рамках, но был при этом человеком надёжным, умным, харизматичным. Человек-крепость, которую тараном не возьмёшь, не то что дипломатией. Такие ассоциации он вызывал."}),(0,l.jsx)(n.p,{children:"Однако в его жизни были две женщины, ради которых он становился совсем другим: жена и дочь. Ни та, ни другая, никогда ни в чём не нуждались. Маттео делал всё, чтобы его семья не знала горестей, давал всё, чтобы те не попросили. Они были богинями в его глазах. Мужчина иногда сам беззлобно удивлялся тому, как же он смог попасть под чары своей супруги Доротеи, не говоря уже о дочери – желанном подарке Господа."}),(0,l.jsx)(n.p,{children:"Стоит сказать, что Орэбелла была единственным ребёнком: мать с не самым крепким здоровьем и хрупким внешне телосложением долго не могла разрешиться от бремени, а до этого пережила неудачные попытки: от смерти дитя вскоре после родов, до выкидыша. Однако Белла, вопреки всему, родилась крепкой и здоровой. Но уже после Доротея утратила возможность родить ещё. И пусть её удручал сей факт, но свою дочь она любила безмерно, как и отец. В воспитание и обучение Летиции вкладывалось баснословное количество времени и средств. Лучшие учителя с ранних лет вкладывали свои знания в голову девочки: этикет, счёт, письмо, литература, языки, философия и другие доступные женщине того времени науки. Кроме перечисленного, Белла обучалась верховой езде, игре на музыкальных инструментах, живописи, но последняя была быстро отброшена ввиду отсутствия должного интереса. Больше всего маленькую дворянку интересовало музицирование и обучение языкам. Но и так стоит сказать, что Летиция была ребенком способным: пусть не схватывала налету и не была какой-то сверх одаренной, но очень способной и усидчивой, на радость преподавателям и родителям. Но главные уроки, уроки жизни, будущей Императрице, давала матушка. Она обучала дочь премудростям жизни, её хитростям и возможным трудностям. Одним из важных направлений было искусство мягкой манипуляции, в которой сама Доротея сильно преуспела и смогла ненавязчиво «выковать» супруга по своему хотению, добиться благоприятного расположения в обществе."}),(0,l.jsx)(n.p,{children:"Понимая, как много ей дают, как много готовы дать, Белла начала откровенно и неоткровенно капризничать. Но ей всё прощалось, и все прихоти, как бы не росли аппетиты, удовлетворялись. В буквальном смысле в том числе. Порой поварам приходилось немало потрудиться в поисках интересных, заморских рецептов различных блюд, чтобы вкусовые рецепторы госпожи остались довольны."}),(0,l.jsx)(n.p,{children:"С возрастом Орэбелла расцветала подобно цветам. Она унаследовала, во многом, черты матери: хрупкое, утонченное телосложение, притягательные черты лица. А в связке с хорошей родословной и наследством она выходила весьма завидной невестой. Околдованные её красотой, грацией, складными речами, мужчины не могли устоять. Многие желали взять в законные жены Миледи Ренальди, да та не торопилась."}),(0,l.jsx)(n.p,{children:"Выбирала, так как считала себя вправе выбирать. Чего греха таить: ей нравилось такое внимание. Все те мужчины приходили не с пустыми руками: помимо пламенных слов они приносили дорогие подарки, редкие и изысканные, балуя Летицию. Да и родители не готовы были так быстро отпускать родную кровь, уж сильно они её любили. К тому же, прежде чем вступить в брак, девушке хотелось повидать мир, насколько то было возможно. И отец не мог отказать своему дитя. Связанный с торговлей, ему приходилось путешествовать. И если определённое время он это делал самостоятельно, то потом брал с собой семью в полном составе. Ах, что это было за время! Орэбелла до сих пор со светлой грустью вспоминает его."}),(0,l.jsx)(n.p,{children:"Но, так или иначе, пришла пора и для брака. Тем самым счастливцем стал виконт Амадео-Винсенте Конте, старший сын и наследник графа Бернардо Конте. Конечно, Белле хотелось познать такую любовь, какая была у её отца и матери, но увы. Тем не менее, она смогла стать супругу другом, остаться верной женой, жить с ним в моральном комфорте, подарить ему потомство, в котором также не чаяла души. Как бы то ни было, но семья и её благополучие всегда имели большое значение в жизни Орэбеллы."}),(0,l.jsx)(n.p,{children:"К слову, ради того самого благополучия, она готова была пойти на не самые благочестивые поступки: имели место ложь, подкуп, получение взяток, и это несмотря на то, что, по сути, Конте не обладала реальной властью, но через податливого супруга могла «протолкнуть» нужные идеи. А также позволяла себе лёгкий, ни к чему не обязывающий флирт. Поначалу было Летиция корила себя за это, но позже лишь подпитывала свои зависимости, не видя в них большого греха. Что тут сказать: некоторая развращённость была посеяна ещё в детстве, а с возрастом лишь прорастала."}),(0,l.jsx)(n.p,{children:"Но, пожалуй, стоит упомянуть некоторый период покаяния, о котором сейчас Белла не вспоминает или воспринимает его под иным углом, нежели тогда. Может ли кто-нибудь поверить в то, что эта прекрасная миледи, доброжелательная и учтивая, способна на убийство? И она не могла, однако успела за свою не очень долгую жизнь отнять чужую жизнь. Более всего девушку поразило то, насколько легко это было. А дело было так: нянечка была неосторожной со старшим сыном Беллы, и та это увидела. В самых скверных чувствах она набросилась хлёсткими словами на уже немолодую женщину, а когда та попыталась уйти от гнева матери, последняя, не найдя в себе сил сдержаться, толкнула няню. Несильно, но этого было достаточно. Достаточно для того, чтобы несчастная покатилась с лестницы и сломала себе шею. Самое обычное клише, но оно очень сильно напугало Орэбеллу в тот момент. Хорошо что эту сцену никто более не видел, и Конте сплела отличную ложь для того, чтобы остаться безнаказанной и даже не порицаемой, а чуть ли не жертвой. Много грехов в тот день совершила Летиция, много времени затем проводила в молитвах. А от семьи погибшей попросту откупилась. Позже девушка, можно сказать, убедила себя в том, что, в общем-то, её вины здесь нет, а няня была наказана Господом за непотребное отношение к ребёнку, но, так или иначе, не могла до конца избавиться от горечи, которую испытывала, стоило только вспомнить тот случай."}),(0,l.jsx)(n.p,{children:"Стоило прежней жизни после непреднамеренного убийства вернуться в прежнее русло, как Беллу настигло новое испытание. Будто бы до этого её оберегал сам Господь от трудностей бытия, но в какой-то момент отвернулся. Почему? Кто знает. Но какой-то был мужчина… Хорош собой, с безупречными манерами, иностранец голубых кровей. Конте потеряла сон из-за него, искала свободную минуту лишь ради общения с ним. Вот она – любовь. Любовь, которую миледи так желала. Ах, если бы он объявился раньше… Но Летиция не позволила этому роману жить. Не просто жить – развиться. Она не была дурой, и вполне трезво осознавала, какие проблемы может на себя наслать. Положение, репутация, семья – кем бы ни был тот мужчина, для Беллы многое стояло на кону."}),(0,l.jsx)(n.p,{children:"Она жестко отвергла свою почти что любовь, посеяла обиду, заставила покинуть Венецию и не вспоминать более о тех светлых минутах, которые подарило ему общество Конте. Она тяжело переживала разрыв, который сама же инициировала, но не жалела о своём решении."}),(0,l.jsx)(n.p,{children:"Последним во всех смыслах серьёзным и значимым испытанием были третьи роды. Вопреки наследственности будущая Императрица довольно легко переносила роды, но не в этот раз. Возраст и предыдущие беременности не прошли бесследно. Орэбелла долго не могла разрешиться от бремени, будто повторяла историю своей матери. Но если последняя всё же осталась в живых, смогла даже недолгое время понянчить внуков и уйти к Господу со спокойным сердцем, то её дочь… Она скончалась спустя недолгое время после родов от горячки, против которой было крайне мало шансов. С печалью в сердце о того, что покидает этот мир, своих детей. Она так много не успела им рассказать, а младенца вовсе оставляет едва ли не одного в этом непростом бытии. То были мучительные минуты: небеса наказывали Орэбеллу-Летицию Конте за грехи её прижизненные."}),(0,l.jsx)(n.p,{children:"Но что же её ожидало в посмертии?"})]})}),(0,l.jsx)(r,{title:"Жизнь в Энкраже",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(x,{children:(0,l.jsx)(n.p,{children:"Неужели Господь оставался глух к моим молитвам?"})}),(0,l.jsx)(n.p,{children:"То были не райские врата, совсем не райские. Поначалу Орэбелла вообще ничего не помнила и не понимала. Одинокая и потерянная, повелевалась она неслышному зову. Спустя время, которого невозможно сосчитать, грешница оказалась в башне, неуютной и холодной. Башня говорила с ней, злым голосом. Он обрушивался на хрупкое сознание Летиции тяжёлым камнем и требовал. Требовал доказать, что Белла достойна идти дальше. Сложно сказать, как всё было на самом деле: возможно, так, а может, восприятие и состояние играли с несчастной злую шутку. Терзаемая испытаниями, будущая Императрица интуитивно хваталась за характер, скованный при жизни и искала новые черты, пробовала их. Её взору являлись разные сцены, ставились сложные задачи – впору лишиться рассудка. Признаться, Белла иногда так и думала. Но за что же её так наказывают? Что же девушка натворила в жизни, за что теперь расплачивается? Собирать себя по кускам, пытаться познать и понять новые законы. Осознать себя умершей. То было время, о котором неприятно вспоминать. Пусть оно послужило хорошим толчком, чувством гордости за себя, за то, что смогла преодолеть, но вновь возвращаться к тем ощущениям не хочется."}),(0,l.jsx)(n.p,{children:"Конте, продолжая пребывать в беспамятстве, попала в общество. О, как же рада была она наконец-то оказаться среди людей. Нелюдей? Это уже было не столь важно. Стряхнуть с себя оковы одиночества, услышать разноголосье, дополнять его. Но то было непростое общество – это был целый клан. И жил он по своим правилам, которые хочешь не хочешь – исполняй. Женское начало, конечно, сыграло юной грешнице на руку: устоявшийся матриархат давал бонусы на старте, но в сущности это мало что значило. Во главе стояла Императрица, и именно она управляла иерархией как мужчин, так и женщин. И ни одна не должна была её затмить. Отголоски прошлой жизни будто смутно подсказывали: Орэбелла была хозяйкой, главной. И ей претило оставаться в тени. Но что она может? Новенькая во всех смыслах: Конте предстояло понять, как выжить в неизвестном мире. Каков он из себя? А что представляет из себя её клан скорпионов? Что из себя представляет сама Летиция? И начался долгий путь наверх. В скором времени грешница поняла, какой образ подходит для того, чтобы безболезненно принимать Энкраж и новую реальность. Робкая невинность, прекрасная и уязвимая, остро нуждающаяся в опеке."}),(0,l.jsx)(n.p,{children:"Орэбелла была красива, заманчива, и это не осталось без внимания со стороны как мужчин, так и женщин. Хотя последние ощущали конкуренцию, что весьма закономерно. Но Конте не выходила из образа ни на секунду, не искала себе угол, чтобы выдохнуть. К тому же, она ещё не знала, какой является на самом деле. Но, прежде всего, девушка была послушной. И это самая трудная часть её пути. Летиция будто была уверена: прежде ей приходилось приказывать, но не исполнять. Только выдержка поможет не сорваться. Стоит остановиться на том, что Белле, как свежей крови, выделили наставницу из числа женщин. Иерархия Акрабуамелу на тот момент уже была такова, что как мужчины, так и женщины, имели своё место в клане. Это можно называть профессией, классом, чином, не суть. Только что прибывшие или не перешедшие в силу обстоятельств на другую ступень социальной лестницы, имели статус «Дитя» и могли там оставаться долгое время. К ним приставлялись наставники, которые обучали и заботились, следили за порядком. Белле досталась не самая порядочная учительница. Она испытывала зависть по отношению к Конте. Красота и невинность последней была очень привлекательна, а любопытство и живой ум намекали, что Орэбелла может далеко пойти. Наставница, которую звали Мэра, понимала, что, как и она, Летиция тоже будет желать большего, лучшего места. И какими бы не были обязанности Мэры, она не могла не поддаться влиянию греха, и к обучению относилась спустя рукава. Но разве юная акрабуамелу, не имея ничего за душой, имела право пожаловаться?"}),(0,l.jsx)(n.p,{children:"Тем не менее, осторожно, шаг за шагом, грешница получала и запоминала информацию. Она бесхитростно и любознательно подходила к любым аспектам: внутренним и внешним. Налаживала связи среди клана, была мила и доброжелательна, готова прийти на помощь, несмотря на палки в колёса, которые ставила Мэра. Чётко усваивала иерархию, искала слабые места, способы продвижения. Очень долго девушка наблюдала, слушала разговоры, учила ритуалы. И за всем этим стремлением возвыситься, едва не пропустила одну важную деталь. Она полюбила свой клан, что бы с ней там не происходило. Каждого по-своему, но факт оставался фактом. Орэбелла не смогла остаться равнодушной, испытывала удовольствие, когда акрабуамелу странствовали, когда обустраивались на месте. Как собирались для разговоров. Она впитывала атмосферу общности и сплочённости. Чувствовала, что на своём месте. Не в иерархии, разумеется, а в целом. Грешница находила утешение в сложные периоды, а таковые имелись. Например, в то время, когда фрагменты прошлой жизни острыми осколками ранили сознание Летиции. Она видела прекрасные периоды своего бытия, полные любви, роскоши. Ах, Венеция! Целостный организм, который пронизывали вены-каналы. Жизнь, которая пышно буйствовала на улицах. Как же Белла тосковала по ней. Как же ей ещё раз хотелось быть обласканной Солнцем, ощутить его тепло на своей коже. Коснуться роскошных тканей, сосчитать грани драгоценных камней. Обнять родных. Но этому не бывать. Сейчас девушка обрела новую семью, которой в силах подарить свою любовь, своё внимание. При этих мыслях её отпускало, придавало сил двигаться дальше."}),(0,l.jsx)(n.p,{children:"Время шло, Орэбелла постепенно укрепляла свои позиции, хоть и оставалась в статусе «Дитя». И в этом не мало помог, как ни странно, мужчина по прозвищу «Буревестник». Но о нём чуть позже. Грешница перестала ограничиваться только повышенным вниманием: мужчины преподносили ей подарки. То были скромные, по меркам клана, украшения, но служили явным сигналом того, что Конте всё делает правильно. Однако нельзя было привлекать к своей персоне слишком много внимания, оно может стать опасным. Белла металась: её жажда обладать возрастала, ещё рано выходить из тени. Ей требовалось время чтобы усмирить свой грех. Тогда Белла прикрывалась болезненным осознанием прошлого, чтобы подумать и успокоиться."}),(0,l.jsx)(n.p,{children:"Так что же на счёт Буревестника? Каган Сезер, несомненно, являлся мужчиной, относился к другой внутренней иерархии, и его удел – воевать и восхищаться женщинами клана, исполнять их прихоти. Но не быть их наставником. Но Сезер имел также глаза и мозг, не слыл дураком. Помня, что и сам когда-то был неокрепшим птенцом, ссылаясь на свои понятия справедливости, он решился на дерзкий поступок – «воспитывать» Беллу. Важно, что сама девушка тонко попросила об этом. Неслыханная дерзость, но ей было мучительно мало тех крупиц, которые давала Мэра. Когда выдавалось время, Каган учил её. Не только премудростям социальной жизни акрабуамелу, а необходимости защищаться. Иметь возможность дать физический отпор. Невероятно, как у Летиции хватало на это сил. Иногда она даже жалела о том, что согласилась, однако гордость и мотивация не позволяли всё бросить. Брать в руки оружие, развивать тело – да это просто немыслимо! Но у неё была цель, ради которой стоило рисковать. К тому же, как впоследствии оказалось, женщины тоже познавали искусство войны. Знакомство с Буревестником стало началом тесного, но тайного до определённого времени, союза, который в будущем сыграет на руку. Но уже сейчас он давал свои плоды."}),(0,l.jsx)(n.p,{children:"Ушли десятилетия на то, чтобы Белла перешла в статус наставниц. Тогда она смогла понять поведение Мэры, ведь фактически оказалась на её месте. Но та в итоге не смогла подняться выше, а значит тактика может оказаться провальной. Конте решила, что не пойдет по этому пути. Оставаясь всё такой же доброжелательной и чуткой, девушка со всем рвением относилась к своим обязанностям. Потому что так Летиция сможет организовать свою свиту, тех, кто поддержит, когда придёт время. Лояльность среди женщин труднее заслужить. Их следует обрабатывать «сызмальства»."}),(0,l.jsx)(n.p,{children:"Параллельно она продолжала общение с Сезером. Так как их связь была сокрыта от глаз других, её обучение тоже растягивалось на годы. Далеко не сразу они перешли от общего к частному. Порой эти двое месяцами не могли уединиться. Однажды парочку даже «заприметили», но, благо, ничего серьёзного никто не увидел. Пришлось врать, ссылаясь на романтическую связь. После этого тоже пришлось затаиться. Не только мужчины сражаются за женское внимание, каким бы крепким не был матриархат. Но в конечном итоге Конте начала познавать тонкости стрельбы из лука, и смогла понять, зачем же Каган «гонял» ее. Не так-то просто было пустить стрелу в цель. Проще, когда она неподвижна, но будет глупо считать, что так будет всегда. Руки должны быть сильными, способными продолжительное время оставлять тетиву натянутой. Важно было положение не только верхних конечностей, но и всего тела. А зрение! Вопиющая несправедливость для стрелка иметь слабые глаза. И даже особое восприятие мира, более информативное и объемное может стать плохим помощником, если не уметь им пользоваться, отделять важное от несущественного. В особенности, когда знаешь или хотя бы интуитивно осознаешь, что в прошлой жизни ориентировался на привычное человеку зрение. У скорпионов всё было иначе. Это уже не говоря о втором обличии, изучению которого Белла в итоге уделила не настолько много внимания, и магических способностях. Помнится, Белла решила, раз она лишена возможности хорошо видеть при торжестве дня, то другие не смогут. И впоследствии изучила «Ложное восприятие». О чём не пожалела. Тренировалась она, разумеется тайно, на соклановцах, иногда чиня откровенные пакости, но безвредные. Девушка не хотела понести наказание за учинённый вред."}),(0,l.jsx)(n.p,{children:"Так и продолжалась её жизнь. Характер, навыки, под влиянием обстоятельств, укреплялись: что-то ненужное отметалось и забывалось, а что-то важное оставалось. Укреплялось и желание идти выше. Быть не просто в рядах Управляющих, нет нет. Белла грезила стать Императрицей. Она смотрела на Магдалину, её силу духа, стойкость, умения, и восхищалась. Правительница удерживала в руках власть не одно столетие – какой бы земной король не позавидовал такому?!"}),(0,l.jsx)(n.p,{children:"Но потом что-то пошло не так. Магдалине, вероятно, наскучила спокойная жизнь в пределах стен. Она знала безопасную зону едва ли не наизусть. Её душа требовала большего. Изучить, завоевать опасные земли. Ведь она так много сделала для этого, нужно было двигаться дальше. Мелкие стычки с Пустыми были просто мелкими стычками. И кто же мог ей перечить? Императрица была сродни богине, слова которой – непреложный закон. Оспорить её желания не мог никто. Что видела Магдалина, когда представляла себе этот подход? Чего больше всего желала от его результатов? Новых богатств? Укрепления общего духа? Сам факт того, что она повела клан на неизведанные земли, что сможет достичь там большего, чем кто-либо ещё. Гордыня или Жадность полностью завладели её душой? Тем не менее, Императрица объявила, что походу быть. Она решила, что для борьбы с Пустыми клан имеет достаточно средств. И пойдут все, одной огромной, невероятно сплочённой семьёй. Логика была проста: чем больше их, тем проще будет отбиваться в случае чего. До сих пор Белла не понимает, как можно было так глупо поступить? Магдалина была правителем слишком долгое время, неужели её ум, инстинкт самосохранения притупились? Сытая, хорошая жизнь наскучила настолько, что Императрица готова была повести себя и остальных, за кого в ответе, на смерть?"}),(0,l.jsx)(n.p,{children:"Такое скопление грешников никого не оставило равнодушным. Много Пустых соблазнились. Довольно быстро началась настоящая бойня, которую Белла много раз видела в кошмарах. Чудовища раздирали всех, до кого дотягивались. Опьянённые полученным, они становились ещё более жадными до душ, и никакая сила неспособна была их остановить. Магия бесполезна. Обычное оружие тоже. Артефактов и особого вооружения катастрофически не хватало. Воцарился хаос, заполняемый воплями зверей и скорпионами. Суматоха и паника мешали принимать вдумчивые решения, исполнять хоть какие-то указания. Довольно быстро клан обратился в бегство. Даже самый преданный Императрице понял, какой это было ошибкой. А цена этой ошибки – жизнь. О, как много скорпионов пало от лап и зубов Пустых. Самым большим ударом была гибель Магдалины. Её артефакт, лук, не помог. Да и не должен был. Возможно, утрачен безвозвратно. Белла не видела, как монстры терзали тело Императрицы, но свидетелей тому событию было полно."}),(0,l.jsx)(n.p,{children:"Они вернулись к замку. Уставшие, с застывшей скорбью и болью на лицах. Словно все они погибли там, до единого. Хранитель, как же позволил ты этому случиться? Где было твоё всемогущество, когда оно было так необходимо? Но Хранитель был глух. Он наказывал, своим бездействием наказывал грешников наглядно. Так, чтобы они навсегда запомнили тот день. Чтобы передавали его из уст в уста следующему поколению. И для других грешников это станет ценным знанием."}),(0,l.jsx)(n.p,{children:"Для клана наступили тёмные времена, времена Смуты. От такого пятна позора никому теперь не отмыться. Даже если юные грешники и никогда не услышат эту историю, то старшие всегда найдут время, чтобы напомнить. Клан ослаб, и он может подвергнуться нападению от внутренних врагов. Без преувеличения, судьба скорпионов висела на волоске. Кроме того, мужчинам открылась прекрасная возможность изменить систему, стать в её главе. Такие потери, весь этот поход случился только потому что все приказы исходили от женщины. Одно поражение обесценило тысячи побед. Так или иначе, правитель был необходим."}),(0,l.jsx)(n.p,{children:"Даже в таких ситуациях нужно было искать возможности. Белле выпал шанс. Она была уверена в своих силах. Регалии уже неважны, времена слишком отчаянные. Она училась на ошибках прошлой Императрицы, и считала, что выучила их больше всех. Столетиями грешница работала на свою репутацию. Да и у неё было хорошее подспорье: женщины, которых она обучала, мужчины, которых она не оставляла без милой улыбки и Сезер. Который, кстати говоря, каким-то образом умудрился выкрасть с поля боя лук Магдалины и хорошенько его припрятать. Летиция пошла с ним на сделку. Каган станет во главе мужчин и будет максимально приближен к Орэбелле. Взамен тот отдаст ей оружие, а также приведёт агитацию среди своих подчиненных."}),(0,l.jsx)(n.p,{children:"Но Конте не одна была такая предприимчивая. Среди кандидаток явственно выделялась Эра, которая была на 15 лет старше Беллы: воинственная, горячая, готовая чинить справедливость. Она была преданной бывшей Императрице, едва ли не дочерью, и, по её мнению, это должно быть более весомым аргументом для того, чтобы занять её место по праву. Как же браво выступала Эра, обещая клану отмщение за павших. Как же дельно звучала. И с какой агрессией обрушивалась на мужчин, дабы те не почувствовали ценнее, чем есть на данный момент. Орэбелла же работала по принципу мягкой силы: пока Эра рвала глотку, Конте оказывала посильную помощь клану, узнавала его ещё лучше, чем раньше. Поначалу она даже потворствовала стремлениям конкурентки, вбивалась к ней в доверие. Пошла на подлость, обозначив готовность помогать Эре с агитацией. Стоит всё же упомянуть, что желающих стать Императрицей было несколько, но истинную конкуренцию Летиция ощущала только в той, к кому якобы примкнула."}),(0,l.jsx)(n.p,{children:"Общение всегда давалось Белле легко. Также просто ей получалось склонять мнение в свою пользу. Ненавязчиво, аккуратно, через невинные вопросы. От скорпиона к скорпиону она проворачивала свои дела. Конте даже создала видимость того, что Эра пусть пока и не стала избранной Императрицей, но была что-то вроде временно исполняющей обязанности. И когда пришло время, Летиция вышла из тени. И урвала свою минуту славы. Которая перетекла впоследствии в годы. В момент общего сбора, который был частым явлением, она вышла вперёд и заговорила. Конте всё продумала: как будет стоять, как и что будет говорить, когда остановиться на паузу, где пустить слезу, добавить дрожи голосу. Девушка условно разделила своё выступление на две части, где сначала будет робкой и мягкой, но затем станет ураганом."}),(0,l.jsxs)(x,{children:[(0,l.jsx)(n.p,{children:"Моя дорогая семья. Братья и сёстры. На нас обрушились мрачные дни и ночи. В наших душах поселилась скорбь, которую едва ли кто-то может описать словами. Ни одна бумага этого не вынесет. Нас терзают болезненные чувства. Наши души изранены, они истекают кровью. Наши глаза полны слёз. Я разделяю эту боль с каждым, и каждый разделяет эту боль со мной. И нам становится немного легче. Вот в чём сила наша. Вот в чём познаётся крепость уз. И это ничто не должно изменить."}),(0,l.jsx)(n.p,{children:"Всё это время я была рядом с вами. Мои уши слышали ваши просьбы, мои уста подсказывали решение. Я плакала и смеялась вместе с вами, делила пищу. Я поддерживала вас также, как и вы поддерживали меня. Мы дарили друг другу так необходимое исцеление и надежду. Надежду на то, что мы всё сможем преодолеть. Как бы не терзал нас Энкраж, мы сможем это пройти. Стать лучше."}),(0,l.jsx)(n.p,{children:"Я понимаю, вы жаждете отмщения. Крови. Но я молю: откажитесь. Всё, что мы получим – очередную бойню. Клянусь, я всё ещё слышу во снах и наяву то, как страшно они погибали. Как просили помощи, спасения. Уйдут столетия на то, чтобы совершить ещё одну попытку. И разве вы хотите пребывать во злобе и ненависти всё это время? Ожесточать свои души? Убиенных теперь не вернёшь. Мы не сможем более услышать их заливистый смех, увидеть их прекрасные лица. Но мы можем оставить в своих сердцах то хорошее, что заточили в свой разум. Чтить их имена, зажигать благовония в их честь, произносить молитвы. Мы можем двигаться дальше, ибо всякое испытание можно преодолеть. Мы можем укрепиться их духом, упрочить наш союз. Оставить распри и споры там, за стеной, на растерзание Пустым. Мы не искупим свои грехи, если станем на кровавый путь мести. Подумайте над моими словами, мои дорогие."})]}),(0,l.jsx)(n.p,{children:"Так она начала уже открыто продвигать свою кандидатуру. Разумеется, Эра была в ярости, требовала объяснений. И Белла никогда не оставалась наедине, когда яростная конкурентка нападала. Чтобы были свидетели. В свою же очередь, благородная Летиция объясняла, что Эра ослеплена яростью и горем, ведь Магдалина была ей как мать. Конте не держала зла, она понимала."}),(0,l.jsx)(n.p,{children:"Прежние решения, новые действия, в конце концов, сыграли на руку: Орэбелла стала Императрицей. Новой матерью, указующим перстом. Вот она – награда за труды. Первым делом, в своём статусе девушка учредила День Почитания – событие, во время которого весь клан вспоминает о погибших как от Пустых, так и тех, кто испустил дух по другим обстоятельствам. И в этот день нужно радоваться, праздновать. Говорить приятные слова живым и мёртвым, исполнять танцы, молиться. И жечь благовония. Всем своим существом показать именно любовь к тем, кто покинул Энкраж. Верить и надеяться, что сейчас они в гораздо более лучшем мире. Конечно, в этой затее было двойное дно. В День Почитания особенно будут вспоминать о событиях за стеной. Освежать в разумах тот ужас, который им посчастливилось пережить."}),(0,l.jsx)(n.p,{children:"Сезера, как и обещала, Конте сделала не только личным телохранителем, а командующим. Все мужчины теперь подчинялись его слову. Но выше всё равно стояла Императрица. Она также постановила, что все женщины должны быть обучены азам сражения – во имя собственной защиты в непредвиденных ситуациях. Белла не отдалилась от подданных. Она всё также была среди них, стараясь услышать и исполнить просьбы. Такая политика должна не просто укрепить положение новоизбранной Императрицы, но и максимально исключить недовольства. Она искала отступников и предлагала им вернуться в семью, ибо только в семье они найдут покой и душевное равновесие. С переменным успехом, ей это даже удавалось."}),(0,l.jsx)(n.p,{children:"Также стоит отметить, что Орэбелла ввела в понятие нормы открытую торговлю с другими грешниками. Грабить замечательно, но иногда стоит вести дела относительно честно. Особенно если это будет усыплять бдительность. Во время походов клан собирал доступные ресурсы и готов был продать или обменять на полезные себе предметы. Либо принимал заказы, которые был в силах исполнить."}),(0,l.jsx)(n.p,{children:"И, что немаловажно, Конте усилила роль жриц. Именно при ней они стали зваться Жрицами Змея, так как Императорский Змей потворствовал алчности – доминирующему греху акрабуамелу. Должно было пересмотреть свои ритуалы и, в случае необходимости, переработать их. И со всей любовью и искренностью возводить молитвы в его честь, ибо «Императорский Змей ведает о наших деяниях и мыслях. Он – наш столп, наша основа. Разве мы не должны быть ему благодарны?». Орэбелла молилась и сама, давая другим пример. И сама верила в то, что говорила. Кроме того, заказала идола в честь покровителя, намекнув, что не мешало бы и остальным поступить также."}),(0,l.jsx)(n.p,{children:"Ввела новую касту – Певчие. Те слагали и исполняли песни как во славу Клана, так и Императорского Змея."}),(0,l.jsx)(n.p,{children:"Все нововведения появлялись постепенно, осторожно, обтекаемо, чтобы услышать в ответ как можно меньше недовольств."}),(0,l.jsx)(n.p,{children:"Какие бы происшествия в годы её правления не происходили, все она старается обернуть себе на пользу. Она любит всех, как мать любит детей своих. Но всё же стоит упомянуть, что одному она уделяет больше внимания, отдаёт больше своих материнских чувств. Имя его – Коул Аркрайт. Совсем ещё юный, он с трудом понимал, куда попал. Парень наивно полагал, что законы ему не писаны, что он умнее. Одной из ночей ему не спалось. Обижаясь и ворча на мир, он не мог найти покоя. И решил, что лучшей идеей будет отыграться на канцере-подростке. Эти звери славятся своей флегматичностью, отчего Коул только пуще злился. И прибег к физическому насилию. Наверное, он больше напугал канцера, и тот в панике едва не затоптал молодого грешника. Белла вовремя это увидела – ей тоже не спалось. Она смогла быстро позвать на помощь, а также едва ли не безрассудно броситься самой. Невзирая на наряды и положение, она упала на колени рядом с перепуганным юнцом, обняла того покрепче, словно заслоняла собой. В тот момент зверя уже вовсю успокаивали, но такой жертвенный жест всё равно казался благородным. «Никогда так больше не делай», чуть напугано и тихо произнесла Императрица, крепче стискивая в объятьях Коула."}),(0,l.jsx)(n.p,{children:"Старая рана саднила, ей было страшно от того, что кто-то ещё пострадает так бессмысленно, как тогда. Со временем, Конте прикипела к парню, что вызывало долю ревности у других. Но она не могла ничего с собой поделать. Возможно, то были также и отголоски прошлой жизни. Материнский инстинкт нужно было куда-то девать. Разумеется, конкретных поблажек Летиция не давала, но то там, то тут, облегчала жизнь и обучение Аркрайта. Несмотря на ревность, клан в целом крайне благосклонно оценил эту ситуацию. Увидел в Белле то, о чем она всегда говорила. О готовности быть рядом, защищать."}),(0,l.jsx)(n.p,{children:"И вот уже 76 лет Орэбелла Летиция Конте является главой клана. Реформатором. И видит Императорский Змей, к свержению или окончательной смерти она не готовится."})]})})]}),(0,l.jsxs)(r,{title:"Дополнительно",children:[(0,l.jsx)(r,{title:"Факты о персонаже",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Начитанность",children:(0,l.jsx)(n.p,{children:"Орэбелла очень начитана. В книгах и свитках она старательно черпает информацию как о внешнем мире, так и о внутреннем. Крайне любит историю, культуру разных народов, населяющих Землю, языки. Моду, питание, развитие, ораторское искусство. Интересы Орэбеллы весьма обширны. Если удаётся, берёт чтиво в походы, затем возвращает обратно в библиотеку. Не редки случаи, когда Императрица искает совета или простого общения у Библиотекаря. Обращает внимание на жизнь и решения правителей разных лет, чтобы учиться на их мудрости или ошибках."})}),(0,l.jsx)(h,{title:"Стиль",children:(0,l.jsx)(n.p,{children:"Старается старым нарядам давать какие-то новые детали, чтобы каждый день быть немного другой. Сама охотно придумывает и дополняет образ, имеет нужный для этого вкус и чувство стиля."})}),(0,l.jsx)(h,{title:"Языки",children:(0,l.jsx)(n.p,{children:"Ещё при жизни выучила несколько языков: помимо итальянского знает французский, немецкий, английский и турецкий, свободно говорит, читает и пишет на них. Уже в посмертии выучила язык клана."})}),(0,l.jsx)(h,{title:"Путешествия",children:(0,l.jsx)(n.p,{children:"Успела увидеть за годы своей жизни порядка 10 разных стран."})}),(0,l.jsx)(h,{title:"Коллекция корон",children:(0,l.jsx)(n.p,{children:"Имеет в своём распоряжении порядка 50 различных корон, тиар, диадем, украшений для головы из драгоценных камней и металлов. Есть в большинстве что-то восточное. Другие украшения сложно сосчитать."})}),(0,l.jsx)(h,{title:"Предпочтения в украшениях",children:(0,l.jsx)(n.p,{children:"Из драгоценных металлов и камней предпочитает что-то схожее с рубинами, изумрудом, жемчугом, золотом. Хотя, разумеется, она любит их все."})}),(0,l.jsx)(h,{title:"Любимые фразы",children:(0,l.jsx)(n.p,{children:"Из постоянных фраз: «Да услышит наши слова Императорский Змей и обратит их на пользу», «Возможность – обратная сторона ошибки», «Разделяй горе так, как разделяешь радость»."})}),(0,l.jsx)(h,{title:"Знание традиций",children:(0,l.jsx)(n.p,{children:"Знает наизусть все танцы, песни и ритуалы клана, а также превосходно – язык."})}),(0,l.jsx)(h,{title:"Нательные рисунки",children:(0,l.jsx)(n.p,{children:"Любит временные рисунки на теле – что-то, что отсылает к культуре клана. Почему временные? Чтобы их затем менять."})})]})}),(0,l.jsx)(r,{title:"Внешность",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(n.p,{children:"Орэбелла словно кукла, которая не меняется, какими бы сильными и злыми не были ветра Энкража. Благодаря или из-за внешности Летиция может показаться наивной, возможно, не слишком умной или легкомысленной, но всё это – заблуждение. Которым девушка, впрочем, охотно пользуется. Её внешность – это меч и щит."}),(0,l.jsx)(n.p,{children:"Соврёт тот, кто скажет, что Орэбелла некрасива. Соврёт и будет проклят на том месте, где стоит, сказав такие слова. Императрица сложена просто идеально, и ростом, и фигурой, и лицом. И она всегда подчёркивает все свои достоинства."}),(0,l.jsx)(n.p,{children:"А теперь подробнее сухих фактов: рост – 173 см, и Конте никогда его не стыдилась. Не сутулилась, в её позвоночнике будто стальной стержень. Вес – 49 кг. Лёгкая, невесомая. Но мышцы, хоть и не явно выражены, крепки подобно канатам благодаря наставничеству Буревестника."}),(0,l.jsx)(n.p,{children:"Лицо и тело не имеют дефектов или каких-то диспропорций: форма лица овальная с чуть заострённым подбородком и достаточно выраженной, но не массивной, нижней линией челюсти, нос небольшой и прямой, кончик едва вздёрнутый, лоб невысокий, большие, но не через чур, глаза серого цвета, брови пышные, ровные, среднего размера. Также средний рот, пухлые губы. Кожа светлая, ровная, гладкая и мягкая. Нет морщин, родинок, шрамов."}),(0,l.jsx)(n.p,{children:"Однако имеется одна тату – особенная, ближе к сердцу. Это метка самого Селен-Тура, и Белла высоко ценит его жест. Знак представляет собой изображение Золотого Змея с чёрными чёткими краями и по контуру тела, таким же цветом обозначены чешуйки. Он со всем изяществом стремится к лучистому Солнцу. Имеет пока небольшие размеры, располагается в ложбинке между грудей и кое-где на неё заходит. Светило же, больше похожее на корону за счёт незаконченной формы круга, располагается немногим выше, на грудине. Тату будет расти по мере получения больших даров и благосклонности от покровителя, сам Змей постепенно изменит облик, сходный с внешностью Зверя Греха, а вокруг его тела распустится прекрасный цветок. Стоит также отметить, что Императрица нередко наносит (не самостоятельно) нательные рисунки: для ритуалов, для души, для образа."}),(0,l.jsx)(n.p,{children:"У неё длинная шея, выраженные ключицы, заметные грудь и ягодицы, но не настолько, чтобы первым делом видеть их, а потом уже остальную Беллу. Пальцы рук тонкие, прямые, изящные. Любой перстень смотрится на них великолепно. Талия выраженная, типа «песочные часы». Стопа 37 размера. Волосы – о эти локоны – каштанового цвета, от природы вьющиеся, длинные, пышные. Имеют здоровый блеск и мягкость."}),(0,l.jsx)(n.p,{children:"Конте полна грации. Её походка и жесты плавные, текучие. Она не просто идёт. Не просто переступает с ноги на ногу, о нет. Императрица, как и подобает, шествует. Сложив руки у живота, она неторопливо, с королевской выправкой, лёгкой поступью преодолевает расстояния. Только в редких случаях её шаг может быть чуть более резким и ускоренным. Все действия Мать делает красиво. Хочется остановиться и взглянуть. Но ещё больше хочется идти рядом, задержаться ещё на минуту, даже если разговор будет ни о чём. За Беллой всегда тянется шлейф ароматов, которые источают тело, одежда и волосы. Девушка всегда выглядит богато и ухожено: одежда сидит на фигуре прекрасно, а утонченные украшения, лёгкий макияж никогда не портят натуральную красоту."}),(0,l.jsx)(n.p,{children:"Из одежды предпочитает непышные, лёгкие платья в пол, но во время походов переодевается в мужской костюм. К прочим украшениям нередко надевает кольца-когти или подобные накладки. Некоторыми даже может вскрывать письма и наносить мелкие порезы, но полноценным оружием это считать нельзя: не настолько оно прочное как минимум."}),(0,l.jsx)(n.p,{children:"Говорит Белла негромко, но уверенно. Её речь чёткая, полная, богатая. Слова произносятся неторопливо, с убаюкивающей ноткой: будто бы Императрицу нереально вывести из себя. Она не имеет привычки повышать голос, перебивать собеседника, но в некоторых случаях использует жест «стоп»: раскрытая ладонь, обращённая к тому, с кем говорит."}),(0,l.jsx)(n.p,{children:"Когда гневается – смотрит крайне пристально, чуть прищуривая глаза. Приподнимает подбородок. Добавляет льдинок в голос, немного резкости, но практически никогда не срывается на крик."}),(0,l.jsx)(n.p,{children:"Не выказывает заметного страха, брезгливости и неприязни."}),(0,l.jsx)(n.p,{children:"В преображённом облике выглядит как императорский скорпион чёрного цвета с лоснящимся хитином без белой полосы по бокам. Размеры стандартные, присущие акрабуамелу, жало крупное, светится глухим жемчужным светом. Тельсон (жало) имеет интенсивный красный окрас, контрастирующий со всей анатомией. После линьки тело приобретает золотистый цвет, который со временем темнеет до стандартного."})]})}),(0,l.jsx)(r,{title:"Навыки и умения",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Стрельба из лука",children:(0,l.jsx)(n.p,{children:"Императрица превосходно стреляет из лука. Она потратила достаточное количество времени на то, чтобы профессионально владеть этим видом оружия, не размениваясь на другие."})}),(0,l.jsx)(h,{title:"Ориентация в пространстве",children:(0,l.jsx)(n.p,{children:"Работает как механорецепторы у пауков. В силу слабого зрения Орэбелла научилась чувствовать мир за счёт внешних вибраций. Причем чем их больше, тем точнее работает этот навык. Расстояние – 100 метров вокруг в вертикальном положении тела, 200 метров – если в горизонтальном. Таким образом подобное умение позволяет получать точную информацию об окружающей обстановке: расположение предметов, их размеры, параметры потенциального противника, источник звуков (рост, вес, как собственный, так и возможного снаряжения, но, если оно в рюкзаке – не его содержимое), атаку (физическую и магическую). Удваивается в промежуточном облике."})}),(0,l.jsx)(h,{title:"Реакция",children:(0,l.jsx)(n.p,{children:"Благодаря отличной ориентации в пространстве Орэбелла обладает повышенной скоростью реакции (лучше всего работает в человеческом облике за счёт небольших габаритов тела. Промежуточный не даст нужной изворотливости). Позволяет ловко уворачиваться от физических и некоторых магических (если позволяет расстояние и скорость снаряда)."})}),(0,l.jsx)(h,{title:"Гибкость",children:(0,l.jsx)(n.p,{children:"Для успешного уворота необходимо иметь натренированное, ловкое тело. Навык развит до уровня профессиональной спортивной гимнастки."})}),(0,l.jsx)(h,{title:"Общение со скорпионами",children:(0,l.jsx)(n.p,{children:"Умение общаться и понимать скорпионов как меньших братьев."})}),(0,l.jsx)(h,{title:"Сила воли",children:(0,l.jsx)(n.p,{children:"Высокая воля. Орэбелла хорошо осознает себя и окружающий мир. Имеет опыт и ценные, объёмные знания. Тем не менее, это может не спасти её от насланных иллюзий или телепатической передачи информации. Разве что от прямых приказов. Сделавший это встретит сопротивление. Однако, если он будет превосходно обучен ментальному воздействию, то у Беллы могут возникнуть проблемы."})}),(0,l.jsx)(h,{title:"Выносливость",children:(0,l.jsx)(n.p,{children:"Выносливость, как в человеческом, так и в неполном облике. В последнем х2 от первого. Кочевой образ жизни + естественная выносливость прародителя расы – скорпионов."})}),(0,l.jsx)(h,{title:"Социальные навыки",children:(0,l.jsx)(n.p,{children:"Чтение, письмо, этикет – набор дочки богатых родителей. Орэбеллу плотно обучали, ей нравилось, и это она перенесла в Энкраж, продолжая совершенствоваться."})}),(0,l.jsx)(h,{title:"Красноречие",children:(0,l.jsx)(n.p,{children:"Красноречие, ораторское искусство. Развивалось как при жизни, так и после смерти. Белла изучала труды лучших умов в этой сфере, отрабатывала как наедине, так и на клане."})}),(0,l.jsx)(h,{title:"Музыка и ритм",children:(0,l.jsx)(n.p,{children:"Чувство ритма, хороший слух. Если при жизни не уделяла должного внимания песням и танцам, то уже после смерти открыла в себе данные таланты, так как принимала активное участие в массовых ритуалах, праздниках. Пожалуй, поэтому и захотела впоследствии выделить касту Певчих. Играет на клавишных и струнных инструментах и немного духовых. Совершенствуется в данный момент (поперечная флейта, свирель)."})}),(0,l.jsx)(h,{title:"Шитьё и каллиграфия",children:(0,l.jsx)(n.p,{children:"Не забыла навыки шитья, в теории помнит технику написания картин. Каллиграфия. Почерк у Императрицы красивый, замысловатый, но понятный. Хотя последнее может варьироваться на случай, если письма захотят перехватить."})}),(0,l.jsx)(h,{title:"Познания в драгоценностях и травах",children:(0,l.jsx)(n.p,{children:"Богатые познания в драгоценностях, травах, приобретённых во время путешествий, а также почерпанных из книг. Глядя на описание и изображение и украшений и материалов к ним, Летиции, несомненно, хотелось свой аналог. А если учитывать, что земных камней в Энкраже нет, то нужно было искать что-то похожее. Этим грешила и предыдущая Императрица."})}),(0,l.jsx)(h,{title:"Верховая езда",children:(0,l.jsx)(n.p,{children:"Местная живность, пригодная для перевозки грешников, всё же имеет свои особенности. Белле в этом помогали прижизненные навыки, так что адаптироваться не составило прямо большого труда."})}),(0,l.jsx)(h,{title:"Макияж и причёски",children:(0,l.jsx)(n.p,{children:"Умение, приобретённое в бытность Дитя, наносить макияж и делать причёски, как лёгкие, так и более сложные."})})]})}),(0,l.jsx)(r,{title:"Слабости",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Низкие температуры",children:(0,l.jsx)(n.p,{children:"Конте не победила воздействие низких температур, от которых сначала возникает медлительность и ощущение слабости, а затем анабиоз."})}),(0,l.jsx)(h,{title:"Огонь",children:(0,l.jsx)(n.p,{children:"Жар пламени, который кажется при одном только виде приносит физическую боль. Даже то, что Мать каким-то образом научилась вести себя достойно рядом с небольшим количеством огня, не приносит спокойствия."})}),(0,l.jsx)(h,{title:"Собственный яд",children:(0,l.jsx)(n.p,{children:"Собственный яд – ах, какое предательство, и тот наносит урон, если от него не избавиться. Вырабатывается порой непозволительно долго."})}),(0,l.jsx)(h,{title:"Слабое зрение",children:(0,l.jsx)(n.p,{children:"Более-менее хорошо Белла видит примерно на 10 метров при умеренном освещении. Из-за яркого возникает резь в глазах, что болезненно, уменьшается дальность зрения примерно в два раза. Дальние объекты, особенно мелких размеров, девушка не видит – окружение размывается, будто глаза всё время слезятся."})}),(0,l.jsx)(h,{title:"Отсутствие укреплений",children:(0,l.jsx)(n.p,{children:"Оболочка не имеет каких-то дополнительных укреплений или пассивной защиты. В промежуточной ипостаси то же касается и человеческой части."})}),(0,l.jsx)(h,{title:"Промежуточный облик",children:(0,l.jsx)(n.p,{children:"В промежуточном облике теряется манёвренность, также жало является менее защищённой частью. В период линьки тело становится менее защищённым. Происходит раз в 5 лет в течение 2-х недель."})})]})}),(0,l.jsx)(r,{title:"Оружие",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Кинжал «Жало»",children:(0,l.jsx)(n.p,{children:"Не имеет каких-то свойств, является обычным оружием. Общая длина – 32 см. Длина клинка – 22 см, длина рукояти – 10 см, заточен с одной стороны, клинок сливается с рукоятью, между указанными частями имеется ограничитель. Клинок имеет волнистую форму. Имеется декор в виде абстрактных узоров золотистого цвета. Покоится в ножнах, ножны могут закрепляться на поясе. Пояс надевается поверх платья/костюма, дополняет общий внешний вид Императрицы. В будущем та надеется придать кинжалу свойства артефакта."})}),(0,l.jsx)(h,{title:"Артефакт «Кокон»",children:(0,l.jsx)(n.p,{children:"Артефакт не боевого типа «Кокон». Имеет форму простого ожерелья: подвеска и цепочка. Подвеска представляет собой кристалл неровного (с оттенками) фиолетового цвета. Размеры: 6 см высота, 3 см ширина. Активация происходит следующим образом: на кристалл нужно подуть 3 секунды. Эффект: «Кокон» образует невидимую оболочку по контурам тела, которая в течение 10 постов защищает владельца от воздействия низких температур (до – 30 градусов), далее уходит на перезарядку 10 постов. Имеет 3 заряда. Может быть перезаряжен, если камень не имеет сколов и средних и глубоких трещин. Сам камень не сверхпрочный. Не разобьётся от падения с высоты до 2-х метров, но разбить его можно, бросив тяжелый предмет."})})]})}),(0,l.jsx)(r,{title:"Связанные персонажи",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Альберто Конте",children:(0,l.jsx)(n.p,{children:"Людской мир. Пра-пра (много раз) внук. Некогда Белла поклялась себе, что никто из её рода не будет жить в недостатке и всегда будет окружен благами, познает роскошную жизнь. Связана с ними фамильными драгоценностями."})}),(0,l.jsx)(h,{title:"Орэбелла Конте (тёзка)",children:(0,l.jsx)(n.p,{children:"Людской мир. Пра-пра (много раз) внучка, названная в честь далекого предка. Связана с ними фамильными драгоценностями."})})]})})]}),(0,l.jsx)(x,{children:(0,l.jsx)(n.p,{children:"Она – наваждение. Прекрасное проклятье. Забыть её греху подобно"})})]})}function s(e,l){throw Error("Expected "+(l?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}e.s(["default",0,function(e={}){let{wrapper:s}={...(0,i.useMDXComponents)(),...e.components};return s?(0,l.jsx)(s,{...e,children:(0,l.jsx)(n,{...e})}):n(e)}])}]);